DP_CSS = '.riscv-dp{max-width:1100px;color-scheme:light;background:#fff}\n.riscv-dp svg.dp-svg{width:100%;max-width:100%;height:auto;display:block;user-select:none}\n.dp-error{padding:10px;border:1px solid #d40000;background:#fff0f0;color:#900;font:13px system-ui,sans-serif}\n.dp-fallback{color:#666;font:13px system-ui,sans-serif}\n.dp-wire{outline:none}\n.dp-wire .hit{stroke:transparent;stroke-width:9;fill:none;stroke-linecap:round;stroke-linejoin:round}\n.dp-wire .line,.dp-wire .chev{stroke:#000;stroke-width:1.1;fill:none;stroke-linejoin:round}\n.dp-wire .head{fill:#000;stroke:none}\n.dp-junc{fill:#000}\n.dp-wire.on .line,.dp-wire.on .chev{stroke:#ff1010;stroke-width:3.2}\n.dp-wire.on .head,.dp-junc.on{fill:#ff1010}\n.dp-junc.on{stroke:#ff1010}\n.dp-wire.thin:not(.editable){pointer-events:none}\n.dp-wire.thin.on .line,.dp-wire.thin.on .chev{stroke-width:1.1}\n.dp-wire.bold .line,.dp-wire.bold .chev{stroke-width:3.2}\n.dp-wire.bold.unset .line,.dp-wire.bold.unset .chev{stroke:#a3a7ab}\n.dp-wire.bold.unset .head{fill:#a3a7ab}\n.dp-wire.bold.off .line,.dp-wire.bold.off .chev{stroke:#000}\n.dp-edit .dp-wire:not(.locked){cursor:pointer}\n.dp-edit .dp-wire:not(.locked):not(.on):hover .line{stroke:#ff8a8a;stroke-width:2.6}\n.dp-edit .dp-wire:not(.locked):hover .head{fill:#ff8a8a}\n.dp-edit .dp-wire:not(.locked).on:hover .line{stroke:#d40000}\n.dp-wire:focus-visible .line{stroke:#0a66ff;stroke-width:2.6}\n.dp-wire.bad .line,.dp-wire.bad .chev{stroke-dasharray:4 2.6}\n.dp-wire.bad:not(.on) .line{stroke-width:2.2}\n.dp-wire.bold.bad .line{stroke-width:3.2}\n.dp-edit .dp-wire.bold:not(.locked):hover .line{stroke-width:3.2}\n.dp-lead{stroke:#8c8c8c;stroke-width:.5;fill:none;pointer-events:none}\n.dp-vbox{display:flex;align-items:center;width:100%;height:100%;box-sizing:border-box;font:600 7px/1 ui-monospace,Menlo,Consolas,monospace;background:#c9c9c9;border:.6px solid #777;border-radius:1.5px;color:#000;overflow:hidden}\n.dp-vbox span{padding-left:2px;color:#444;user-select:none}\n.dp-vbox input{flex:1;min-width:0;width:100%;height:100%;border:0;background:transparent;font:inherit;color:#000;padding:0 1px;margin:0;outline:none;text-align:left}\n.dp-vbox:focus-within{background:#e8e8e8;outline:1.4px solid #0a66ff}\n.dp-vbox.bad{background:#ffd6d6;outline:1.4px solid #d40000}\n.dp-vbox.good{outline:1.4px solid #1a8a2e}\n'
