WIZ_CSS = '.dpw{max-width:1100px;font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;color:#111}\n.dpw-top{display:flex;flex-wrap:wrap;gap:10px 18px;align-items:center;justify-content:space-between;margin-bottom:6px}\n.dpw-steps{display:flex;gap:6px;flex-wrap:wrap}\n.dpw-pill{padding:2px 10px;border-radius:999px;background:#e9ecef;color:#495057;font-size:13px;white-space:nowrap}\n.dpw-pill.cur{background:#0a66ff;color:#fff;font-weight:600}\n.dpw-pill.done{background:#d3f9d8;color:#1b5e20}\n.dpw-load{font-size:13px;color:#495057}\n.dpw-load input{font-size:13px;max-width:220px}\n.dpw h4{margin:8px 0 2px;font-size:19px}\n.dpw-help{margin:0 0 8px;color:#343a40}\n.dpw-info{font-size:13px;color:#495057;margin:2px 0 8px}\n.dpw-msg{min-height:0;margin:6px 0;padding:0;font-size:14px}\n.dpw-msg.err{padding:8px 10px;border:1px solid #d40000;background:#fff0f0;color:#900;border-radius:6px}\n.dpw-msg.ok{padding:8px 10px;border:1px solid #1a8a2e;background:#f0fff2;color:#145a22;border-radius:6px}\n.dpw-bar{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}\n.dpw-btn{font:inherit;font-size:14px;padding:6px 14px;border:1px solid #868e96;border-radius:6px;background:#f1f3f5;color:#111;cursor:pointer}\n.dpw-btn:hover{background:#e3e7ea}\n.dpw-btn.primary{background:#0a66ff;border-color:#0a66ff;color:#fff;font-weight:600}\n.dpw-btn.primary:hover{background:#0857d6}\n.dpw-btn.danger{color:#a30000;border-color:#e0a0a0}\n.dpw-final{margin-top:10px}\n.dpw-final label{display:block;font-weight:600;margin:10px 0 3px}\n.dpw-final input[type=text]{width:100%;max-width:520px;font:15px ui-monospace,Menlo,Consolas,monospace;padding:5px 8px;border:1px solid #868e96;border-radius:6px}\n.dpw-final textarea{width:100%;height:230px;font:12px/1.35 ui-monospace,Menlo,Consolas,monospace;padding:8px;border:1px solid #868e96;border-radius:6px;background:#f8f9fa;box-sizing:border-box}\n.dpw-steps-list{margin:8px 0 0;padding-left:20px;color:#343a40;font-size:14px}\n.dpw-diagram-wrap{overflow-x:auto}\n\n.dpw-pre label{display:block;font-weight:600;margin:10px 0 3px}\n.dpw-pre input[type=text],.dpw-pre select{font:15px ui-monospace,Menlo,Consolas,monospace;padding:5px 8px;border:1px solid #868e96;border-radius:6px;width:100%;max-width:520px;box-sizing:border-box}\n.dpw-pre .dpw-check{font-weight:400;display:block;margin:12px 0 4px}\n.dpw-pre .dpw-check input{width:auto;margin-right:6px}\n.dpw-edit{margin-top:18px;font-size:14px}\n.dpw-edit textarea{width:100%;height:120px;font:12px/1.35 ui-monospace,Menlo,Consolas,monospace;padding:8px;border:1px solid #868e96;border-radius:6px;box-sizing:border-box}\n.dpw [hidden]{display:none !important}\n'
WIZ_BODY = '<div class="dpw" id="dpw">\n  <div class="dpw-top"><div class="dpw-steps" id="dpw-steps"></div></div>\n  <h4 id="dpw-title">Loading&hellip;</h4>\n  <p class="dpw-help" id="dpw-help">If this message stays, JavaScript in this question is not running: press F12 and check the Console for red errors.</p>\n  <div class="dpw-info" id="dpw-info"></div>\n  <div class="dpw-msg" id="dpw-msg" role="alert"></div>\n  <div class="dpw-pre" id="dpw-pre" hidden>\n    <label for="dpw-instr">Instruction</label>\n    <input type="text" id="dpw-instr" placeholder="e.g. andi x5, x6, 0x1" autocomplete="off" spellcheck="false">\n    <div id="dpw-branchrow" hidden>\n      <label for="dpw-taken">Branch outcome</label>\n      <select id="dpw-taken"><option value="true">taken</option><option value="false">not taken</option></select>\n    </div>\n    <label class="dpw-check"><input type="checkbox" id="dpw-ctl"> Also add value boxes for the control signals (PCSel, RegWEn, BSel, ASel, MemRW, WBSel, BrUn)</label>\n    <div class="dpw-bar" id="dpw-prebar"></div>\n    <details class="dpw-edit"><summary>Edit an existing problem</summary>\n      <p class="dpw-help">Paste the <code>&lt;pl-riscv-datapath&gt;</code> tag from its <code>question.html</code>.</p>\n      <textarea id="dpw-paste" spellcheck="false" placeholder="&lt;pl-riscv-datapath answers-name=&quot;dp&quot; ...&gt;&lt;/pl-riscv-datapath&gt;"></textarea>\n      <div class="dpw-bar" id="dpw-loadbar"></div>\n    </details>\n  </div>\n  <div class="dpw-bar" id="dpw-bar"></div>\n  <div class="dpw-diagram-wrap" id="dpw-diagram-wrap"><div class="riscv-dp" id="dpw-diagram" data-init="1"></div></div>\n  <div class="dpw-final" id="dpw-final" hidden>\n    <label for="dpw-name">answers-name (any short name, unique within the question)</label>\n    <input type="text" id="dpw-name" value="dp" autocomplete="off" spellcheck="false">\n    <label for="dpw-out">Tag to paste into question.html</label>\n    <textarea id="dpw-out" readonly spellcheck="false"></textarea>\n    <div class="dpw-bar" id="dpw-bar2"></div>\n    <ol class="dpw-steps-list">\n      <li>Open the question\'s <code>question.html</code> in PrairieLearn (Files, then Edit).</li>\n      <li>Paste the tag where the diagram should appear, and write your question text around it. Put the text inside a <code>&lt;pl-question-panel&gt;</code> so it only shows in the question.</li>\n      <li>Save, open <b>Preview</b>, and grade the correct answer once to confirm full marks.</li>\n    </ol>\n  </div>\n</div>\n'

CONTROL_WIRES = ["pcsel__pcmux_sel", "regwen__reg_wen", "immsel__immgen", "brun__brcomp", "brcomp_breq__ctrl",
                 "brcomp_brlt__ctrl", "bsel__bmux_sel", "asel__amux_sel", "alusel__alu", "memrw__dmem", "wbsel__wbmux_sel"]
ATTRIBS = {"answers-name", "mode", "instruction", "branch-taken", "answer-wires", "bold-wires", "initial-wires",
           "initial-off-wires", "locked-wires", "value-boxes", "scoring-mode", "wire-points", "value-points", "weight"}
WIRE_ATTRIBS = {"name", "state", "value", "initial", "locked", "bold"}
SCORING_MODES = ("on_items", "subtract", "all_segments")
TAG = "pl-riscv-datapath"


# ---------------------------------------------------------------- helpers
def _err(msg):
    return ValueError("%s: %s" % (TAG, msg))


def _split(s):
    return [t for t in re.split(r"[,\s]+", s or "") if t]


def _hex(s):
    """'0x1F' / '1f' / '01' -> int, or None when not valid hex."""
    if isinstance(s, int) and not isinstance(s, bool):
        return s
    s = str(s).strip().lower().replace("_", "")
    if s.startswith("0x"):
        s = s[2:]
    if not s or any(c not in "0123456789abcdef" for c in s):
        return None
    return int(s, 16)


def _label(w):
    return w.replace("__", " \u2192 ").replace("_", " ")


def _element(element_html):
    return lxml.html.fragment_fromstring(element_html)


def _is_builder(el):
    return (el.get("mode") or "").strip().lower() == "builder"


def _name(el):
    name = (el.get("answers-name") or "").strip()
    if not name:
        raise _err("answers-name is required")
    return name


def _part_matches(part, token):
    return part == token or part.startswith(token + "_")


def _wire_list(value, what):
    """Wire names, or groups: all | control | to:<component> | from:<component> (e.g. to:wbmux)."""
    out = []
    for tok in _split(value):
        low = tok.lower()
        if tok in WIRE_IDS:
            found = [tok]
        elif low == "all":
            found = list(WIRE_IDS)
        elif low == "control":
            found = list(CONTROL_WIRES)
        elif low.startswith("to:") or low.startswith("from:"):
            side, comp = low.split(":", 1)
            idx = 1 if side == "to" else 0
            found = [w for w in WIRE_IDS if _part_matches(w.split("__")[idx], comp)]
            if not found:
                raise _err("%r in %s matches no wires" % (tok, what))
        else:
            raise _err("unknown wire or group %r in %s (use a wire name, all, control, to:<component> or from:<component>)"
                       % (tok, what))
        out += found
    return out


def _box_value(w, raw, what):
    v = _hex(raw)
    if v is None:
        raise _err("%s: %r is not a valid hex value" % (what, raw))
    if v.bit_length() > 4 * WIRE_DIGITS[w]:
        raise _err("%s: %r needs more than %d hex digits" % (what, raw, WIRE_DIGITS[w]))
    return format(v, "x")


def _number(el, attr, default):
    raw = el.get(attr)
    if raw is None:
        return default
    try:
        v = float(raw)
    except ValueError:
        raise _err("%s must be a number" % attr)
    if v < 0:
        raise _err("%s must not be negative" % attr)
    return int(v) if v == int(v) else v


# ---------------------------------------------------------------- the answer key
def _build_spec(el):
    """Turn the tag (attributes, <pl-wire> children) into a JSON-serializable key."""
    unknown = set(el.attrib) - ATTRIBS
    if unknown:
        raise _err("unknown attribute(s): %s. Allowed: %s" % (", ".join(sorted(unknown)), ", ".join(sorted(ATTRIBS))))
    _name(el)
    on, boxes, ctl = set(), {}, {}

    instruction = (el.get("instruction") or "").strip()
    if el.get("answer-wires") is not None:
        on = set(_wire_list(el.get("answer-wires"), "answer-wires"))
    elif instruction:
        tok = instruction.split()[0].lower().rstrip(",")
        mnemonic = ALIASES.get(tok, tok)
        preset = PRESETS.get(mnemonic)
        if preset is None:
            known = sorted(set(PRESETS) | set(ALIASES))
            raise _err("no preset for instruction %r. Supported: %s. Or give answer-wires / <pl-wire> children."
                       % (tok, ", ".join(known)))
        if preset.get("branch"):
            taken = (el.get("branch-taken") or "").strip().lower()
            if taken not in ("true", "false"):
                raise _err('%s is a branch: set branch-taken="true" or branch-taken="false"' % mnemonic)
            preset = preset["taken" if taken == "true" else "not_taken"]
        on = set(preset["on"])
        ctl = dict(preset["ctl"])

    vb = (el.get("value-boxes") or "none").strip().lower()
    if vb != "none":
        if not ctl:
            raise _err("value-boxes needs an instruction (it takes the values from the preset)")
        names = list(ctl) if vb == "control" else _split(vb)
        for n in names:
            if n not in CONTROL:
                raise _err("unknown control signal %r in value-boxes. Use: %s" % (n, ", ".join(CONTROL)))
            if n not in ctl:
                raise _err("%s has no defined value for this instruction, so it cannot be a value box" % n)
            boxes[CONTROL[n]] = format(int(ctl[n]), "x")

    bold = set(_wire_list(el.get("bold-wires"), "bold-wires")) if el.get("bold-wires") is not None else None
    if bold is not None and not bold:
        raise _err("bold-wires is empty")
    directive = {}                       # wire -> "on" | "off" | "unset"  (starting state)
    for w in _wire_list(el.get("initial-wires"), "initial-wires"):
        directive[w] = "on"
    for w in _wire_list(el.get("initial-off-wires"), "initial-off-wires"):
        directive[w] = "off"
    locked = set(_wire_list(el.get("locked-wires"), "locked-wires"))

    for child in el.iter("pl-wire"):
        bad = set(child.attrib) - WIRE_ATTRIBS
        if bad:
            raise _err("<pl-wire> has unknown attribute(s): %s" % ", ".join(sorted(bad)))
        w = (child.get("name") or "").strip()
        if w not in WIRE_IDS:
            raise _err("<pl-wire> has unknown wire name %r" % w)
        state = child.get("state")
        if state is not None:
            state = state.strip().lower()
            if state == "on":
                on.add(w)
            elif state == "off":
                on.discard(w)
            else:
                raise _err('<pl-wire name="%s"> state must be "on" or "off"' % w)
        if child.get("value") is not None:
            boxes[w] = _box_value(w, child.get("value"), '<pl-wire name="%s">' % w)
        b = child.get("bold")
        if b is not None:
            if bold is None:
                bold = set()
            if b.strip().lower() in ("true", "on"):
                bold.add(w)
            elif b.strip().lower() in ("false", "off"):
                bold.discard(w)
            else:
                raise _err('<pl-wire name="%s"> bold must be true or false' % w)
        i = child.get("initial")
        if i is not None:
            i = i.strip().lower()
            if i in ("on", "true"):
                directive[w] = "on"
            elif i in ("off", "false"):
                directive[w] = "off"
            elif i == "unset":
                directive[w] = "unset"
            else:
                raise _err('<pl-wire name="%s"> initial must be on, off or unset' % w)
        v = child.get("locked")
        if v is not None:
            if v.strip().lower() in ("true", "on"):
                locked.add(w)
            elif v.strip().lower() in ("false", "off"):
                locked.discard(w)
            else:
                raise _err('<pl-wire name="%s"> locked must be true or false' % w)

    mode = (el.get("scoring-mode") or "on_items").strip().lower()
    if mode not in SCORING_MODES:
        raise _err("scoring-mode must be one of %s" % ", ".join(SCORING_MODES))
    if bold is not None:
        if not bold:
            raise _err("bold-wires is empty (no wire is marked bold)")
        if el.get("scoring-mode") is not None:
            raise _err("scoring-mode does not apply when bold-wires is set (each bold wire is one item)")
        # bold wires: red / black / unset start; thin wires: a start of "on" shows them thin red (fixed, not clickable)
        initial = {w for w, d in directive.items() if d == "on"}
        initial_off = {w for w, d in directive.items() if d == "off" and w in bold}
    else:
        if el.get("initial-off-wires") is not None:
            raise _err("initial-off-wires only applies when bold-wires is set")
        initial = {w for w, d in directive.items() if d == "on"}
        initial_off = set()
    has_source = bool(instruction) or el.get("answer-wires") is not None or any(c.get("state") for c in el.iter("pl-wire"))
    if not has_source and not boxes:
        raise _err("no answer key: give an instruction, answer-wires, or <pl-wire state=\"on\"> children")

    order = {w: i for i, w in enumerate(WIRE_IDS)}
    srt = lambda xs: sorted(xs, key=order.get)
    return {
        "on": srt(on),
        "bold": srt(bold) if bold is not None else None,
        "boxes": {w: boxes[w] for w in srt(boxes)},
        "initial": srt(initial),
        "initial_off": srt(initial_off),
        "locked": srt(locked),
        "scoring": {"mode": mode, "wire_point": _number(el, "wire-points", 1), "value_point": _number(el, "value-points", 1)},
        "weight": int(_number(el, "weight", 1)),
    }


def _score(spec, on, values, off=()):
    """Grade one submission. on / off: sets of wire ids set red / black; values: {wire: hex string}."""
    off = set(off)
    key_on = set(spec["on"])
    bold = spec.get("bold")
    wp, vp = spec["scoring"]["wire_point"], spec["scoring"]["value_point"]
    if bold:
        b = set(bold)
        good = {w for w in b if (w in on and w in key_on) or (w in off and w not in key_on)}
        results = {w: False for w in sorted(b - good)}       # dashed: wrong or not set
        earned, possible = wp * len(good), wp * len(b)
        detail = "%d bold wire(s) incorrect or not set (dashed)" % len(b - good)
    else:
        right, extra = on & key_on, on - key_on
        allres = {w: ((w in on) == (w in key_on)) for w in WIRE_IDS}
        results = {w: ok for w, ok in allres.items() if not ok}
        mode = spec["scoring"]["mode"]
        if mode == "all_segments":
            earned, possible = wp * sum(allres.values()), wp * len(WIRE_IDS)
        elif mode == "subtract":
            earned, possible = wp * (len(right) - len(extra)), wp * len(key_on)
        else:
            earned, possible = wp * len(right), wp * (len(key_on) + len(extra))
        detail = "%d wire segment(s) missing, %d turned on that should be off (dashed)" % (len(key_on - on), len(extra))
    vres = {}
    for w, correct in spec["boxes"].items():
        got = _hex(values.get(w, ""))
        vres[w] = got is not None and got == _hex(correct)
        earned += vp * vres[w]
        possible += vp
    score = max(0.0, min(1.0, earned / possible)) if possible else 0.0
    summary = "%s/%s points: %s." % (format(max(0, earned), "g"), format(possible, "g"), detail)
    return score, summary, results, vres


# ---------------------------------------------------------------- rendering
def _attr(obj):
    return html.escape(json.dumps(obj, separators=(",", ":")), quote=True)


def _assets(js, css):
    return "<style>\n%s\n</style>\n<script>\n%s\n</script>\n" % (css, js)


def _diagram(name, mode, spec, state=None, results=None, vresults=None, hidden=False):
    preset = {w: 1 for w in spec["initial"]}
    preset.update({w: 0 for w in spec.get("initial_off", [])})
    cfg = {"fill": {w: True for w in spec["boxes"]}, "preset": preset, "locked": spec["locked"]}
    if spec.get("bold"):
        cfg["bold"] = spec["bold"]
    a = ['class="riscv-dp"', 'data-mode="%s"' % mode, 'data-combined="1"', 'data-input="%s"' % html.escape(name, quote=True),
         'data-config="%s"' % _attr(cfg)]
    if state is not None:
        a.append('data-state="%s"' % _attr(state))
    if results is not None:
        a.append('data-results="%s"' % _attr(results))
    if vresults is not None:
        a.append('data-vresults="%s"' % _attr(vresults))
    out = '<div %s><p class="dp-fallback">Loading datapath diagram&hellip; (if this message stays, JavaScript is not running: '\
          'press F12 and check the Console for red errors)</p></div>\n' % " ".join(a)
    if hidden:
        out += '<input type="hidden" name="%s">\n' % html.escape(name, quote=True)
    return out


def _submission_state(sub):
    """Submitted answer (dict after parse, or raw JSON string) -> {'wires': {id: 1|0}, 'values': {...}} or None."""
    if isinstance(sub, str):
        try:
            sub = json.loads(sub)
        except ValueError:
            return None
    if not isinstance(sub, dict):
        return None
    wires = sub.get("wires")
    if isinstance(wires, list):
        wires = {w: 1 for w in wires}
        wires.update({w: 0 for w in (sub.get("off") or [])})
    return {"wires": wires if isinstance(wires, dict) else {}, "values": sub.get("values") if isinstance(sub.get("values"), dict) else {}}


def render(element_html, data):
    el = _element(element_html)
    panel = data["panel"]
    if _is_builder(el):
        if panel != "question":
            return ""
        return ('<style>\n%s\n</style>\n%s\n<script>\n%s\n</script>\n<script>\n%s\n</script>\n'
                % (DP_CSS + "\n" + WIZ_CSS, WIZ_BODY, DP_JS, WIZ_JS))
    name = _name(el)
    spec = data["correct_answers"].get(name)
    if spec is None:
        raise _err("no answer key for %r (was prepare() run?)" % name)
    assets = _assets(DP_JS, DP_CSS)
    errors = data["format_errors"].get(name)
    sub = _submission_state(data["submitted_answers"].get(name))

    if panel == "question":
        editable = bool(data.get("editable", True))
        body = _diagram(name, "edit" if editable else "view", spec, state=sub, hidden=editable)
        if errors:
            body += '<div class="alert alert-danger" role="alert">%s</div>\n' % html.escape(str(errors))
        return body + assets
    if panel == "submission":
        if errors:
            return '<div class="alert alert-danger" role="alert">%s</div>\n' % html.escape(str(errors))
        if sub is None:
            return ""
        fb = data["feedback"].get(name) or {}
        summary = html.escape(fb.get("summary", ""))
        body = ('<p>%s</p>\n' % summary if summary else "")
        body += _diagram(name, "view", spec, state=sub, results=fb.get("results"), vresults=fb.get("vresults"))
        return body + assets
    if panel == "answer":
        key_on = set(spec["on"])
        if spec.get("bold"):
            wires = {w: (1 if w in key_on else 0) for w in spec["bold"]}
        else:
            wires = {w: 1 for w in spec["on"]}
        return _diagram(name, "view", spec, state={"wires": wires, "values": spec["boxes"]}) + assets
    return ""


# ---------------------------------------------------------------- PrairieLearn phases
def prepare(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    data["correct_answers"][_name(el)] = _build_spec(el)


def parse(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    name = _name(el)
    raw = data["submitted_answers"].get(name)
    obj = None
    if isinstance(raw, dict):
        obj = raw
    elif isinstance(raw, str) and raw.strip():
        try:
            obj = json.loads(raw)
        except ValueError:
            obj = None
    if not isinstance(obj, dict):
        data["format_errors"][name] = "No answer was received from the diagram. Please try again."
        return
    wires = obj.get("wires", {})
    if isinstance(wires, list):
        wires = {w: 1 for w in wires}
        wires.update({w: 0 for w in (obj.get("off") or [])})
    values = obj.get("values", {})
    if not isinstance(wires, dict) or not isinstance(values, dict):
        data["format_errors"][name] = "The diagram answer was malformed. Please try again."
        return
    on = [w for w in WIRE_IDS if wires.get(w)]
    off = [w for w in WIRE_IDS if w in wires and not wires[w]]
    clean = {}
    for w, v in values.items():
        if w not in WIRE_IDS:
            continue
        v = str(v or "").strip()
        if v and _hex(v) is None:
            data["format_errors"][name] = "The value on %s is not valid hexadecimal." % _label(w)
            return
        clean[w] = v
    data["submitted_answers"][name] = {"wires": on, "off": off, "values": clean}


def grade(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    name = _name(el)
    spec = data["correct_answers"][name]
    sub = data["submitted_answers"].get(name)
    if not isinstance(sub, dict):
        return
    score, summary, results, vres = _score(spec, set(sub["wires"]), sub["values"], sub.get("off", []))
    data["partial_scores"][name] = {"score": score, "weight": spec["weight"], "feedback": summary}
    data["feedback"][name] = {"results": results, "vresults": vres, "summary": summary}


def test(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    name = _name(el)
    spec = data["correct_answers"][name]
    kind = data["test_type"]
    key_on = set(spec["on"])
    if spec.get("bold"):
        good = {w: (1 if w in key_on else 0) for w in spec["bold"]}
    else:
        good = {w: 1 for w in spec["on"]}
    if kind == "correct":
        data["raw_submitted_answers"][name] = json.dumps({"wires": good, "values": spec["boxes"]})
        data["partial_scores"][name] = {"score": 1, "weight": spec["weight"]}
    elif kind == "incorrect":
        wires = dict(good)
        if spec.get("bold"):
            first = spec["bold"][0]
            wires[first] = 0 if wires[first] else 1
        else:
            wires[next(w for w in WIRE_IDS if w not in good)] = 1
        on = {w for w, v in wires.items() if v}
        off = {w for w, v in wires.items() if not v}
        score, _, _, _ = _score(spec, on, spec["boxes"], off)
        data["raw_submitted_answers"][name] = json.dumps({"wires": wires, "values": spec["boxes"]})
        data["partial_scores"][name] = {"score": score, "weight": spec["weight"]}
    elif kind == "invalid":
        data["raw_submitted_answers"][name] = "this is not json"
        data["format_errors"][name] = "No answer was received from the diagram. Please try again."
    else:
        raise _err("unknown test_type %r" % kind)
